-- Institution upload portal: roles, upload window, one-time criterion submissions.
ALTER TABLE users ADD COLUMN IF NOT EXISTS institution_id TEXT NOT NULL DEFAULT '';

ALTER TABLE attachments ADD COLUMN IF NOT EXISTS source TEXT NOT NULL DEFAULT 'evaluator';
ALTER TABLE attachments ADD COLUMN IF NOT EXISTS responsible_name TEXT NOT NULL DEFAULT '';
ALTER TABLE attachments ADD COLUMN IF NOT EXISTS responsible_phone TEXT NOT NULL DEFAULT '';
ALTER TABLE attachments ADD COLUMN IF NOT EXISTS submission_date DATE;

CREATE TABLE IF NOT EXISTS system_settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL DEFAULT '',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ON CONFLICT (key) DO NOTHING;

CREATE UNIQUE INDEX IF NOT EXISTS institution_once_per_criterion_date
  ON attachments (institution_id, criterion_id, submission_date)
  WHERE source = 'institution' AND submission_date IS NOT NULL;

